ea:MeasuredLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  skos:altLabel "objective" .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome .
[] a owl:AllDisjointClasses ;
  owl:members ( ea:IntendedLearningOutcome ea:MeasuredLearningOutcome ea:UnintendedLearningOutcome ) .

ea:LearningOutcomeTaxonomy a owl:Class .
ea:BloomsTaxonomy a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:StructureOfObservedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy ;
  skos:altLabel "SOLO" .
ea:DikwPyramid a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:ModelOfHierarchicalComplexity a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .

#################################################################
# LEARNING TYPES (formal / non-formal / informal)
#################################################################

ea:FormalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:NonFormalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Organized learning outside the formal learning system." .
ea:InformalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Less structured than non-formal learning; occurs through day-to-day experience." .
[] a owl:AllDisjointClasses ;
  owl:members ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) .

#################################################################
# TRANSFER OF LEARNING
#################################################################

ea:TransferOfLearning a owl:Class .
ea:NearTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning .
ea:FarTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning .
[] a owl:AllDisjointClasses ; owl:members ( ea:NearTransfer ea:FarTransfer ) .

ea:PositiveTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning .
ea:NegativeTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning .
[] a owl:AllDisjointClasses ; owl:members ( ea:PositiveTransfer ea:NegativeTransfer ) .

#################################################################
# FEEDBACK
#################################################################

ea:CorrectiveFeedback a owl:Class ; rdfs:subClassOf ea:Feedback .
ea:Recast a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback .

#################################################################
# PORTFOLIOS
#################################################################

ea:CapstonePortfolio a owl:Class ; rdfs:subClassOf ea:StudentPortfolio .
ea:DigitalPortfolio a owl:Class ; rdfs:subClassOf ea:StudentPortfolio ;
  skos:altLabel "e-portfolio" .

#################################################################
# PROFICIENCY, MEASUREMENT ERROR, SCORE INFLATION, VALUE-ADDED
#################################################################

ea:TestProficiencyLevel a owl:Class ; rdfs:subClassOf ea:Proficiency ;
  rdfs:comment "Proficiency levels, scales and cut-off scores on standardized tests." .
ea:StudentProficiencyAttainment a owl:Class ; rdfs:subClassOf ea:Proficiency ;
  rdfs:comment "Students achieving or failing to achieve proficiency levels." .
ea:StandardsProficiency a owl:Class ; rdfs:subClassOf ea:Proficiency ;
  rdfs:comment "Students demonstrating or failing to demonstrate proficiency with respect to learning standards." .
ea:TeacherProficiencyRating a owl:Class ; rdfs:subClassOf ea:Proficiency ;
  rdfs:comment "Teachers deemed proficient or non-proficient on job-performance evaluations." .

ea:TestScoreMeasurementError a owl:Class ; rdfs:subClassOf ea:MeasurementError ;
  rdfs:comment "Difference between what a test score indicates and a student's actual knowledge/abilities." .
ea:DataReportingMeasurementError a owl:Class ; rdfs:subClassOf ea:MeasurementError ;
  rdfs:comment "Errors introduced when collecting and calculating data-based reports, figures and statistics." .
[] a owl:AllDisjointClasses ; owl:members ( ea:TestScoreMeasurementError ea:DataReportingMeasurementError ) .

ea:ValueAddedMeasure a owl:Class ; rdfs:subClassOf ea:TeacherEvaluationMeasure ;
  skos:altLabel "growth measure" .
ea:StudentGrowthMeasure a owl:Class ; rdfs:subClassOf ea:TeacherEvaluationMeasure ;
  rdfs:comment "'A related — but distinct — method' from value-added measures." .
[] a owl:AllDisjointClasses ; owl:members ( ea:ValueAddedMeasure ea:StudentGrowthMeasure ) .
